"use client";

import * as React from "react";
import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { cn } from "@/lib/utils";
import {
  caretUnits,
  decimalFor,
  isDigit,
  matchText,
  textUnits,
  type GlyphKind,
} from "./lib/match";
import {
  resolveOptions,
  type TextMorphOptions,
  type TextMorphOverrides,
} from "./lib/options";
import "./text-morph.css";

/*
 * Animated text for labels that change in place.
 *
 * The server renders the label already split into one span per glyph, as
 * fixed HTML that this component owns from then on. The browser receives
 * identical markup, so hydration changes nothing and nothing is measured at
 * load. Work happens only when the value changes:
 *
 *   1. Snapshot every visible glyph's on-screen box, including whatever
 *      animation it's mid-way through. Starting from there is what makes a
 *      change that lands mid-animation pick up smoothly instead of jumping.
 *   2. Reuse the glyph nodes the old and new text share, create the new
 *      ones, and move the removed ones to a ghost layer to animate out.
 *   3. Measure the final layout, then animate each glyph from its snapshot.
 *
 * The label flows inline like the text around it, grouped into words so
 * lines only break between them, and it never changes display: switching
 * an element between inline and inline-block repaints its text snapped
 * differently, a visible shimmer as it settles. A change that stays on one
 * line eases the space it takes with its start margin, so the text after
 * it slides rather than jumps. A start margin rather than an end one: line
 * breaking counts it before the glyphs, so a growing value never overruns
 * the space it had and breaks away from the text before it. The stage rides
 * against the label's moving start (`left`, which inline boxes honour) on
 * the same curve, so the glyphs never drift with it. Both
 * run on the main thread from one clock: a transform would run on the
 * compositor and keep going while a busy main thread held the layout
 * still. A change that wraps keeps the lines as the layout, and glyphs
 * travel to their new places across them.
 *
 * Leaving glyphs (ghosts) sit in a layer measured and sized each change,
 * each in a slot at its own line that fades it out above and below. A new
 * glyph landing where its own text is still leaving takes that ghost back.
 * The slots fade only while a change plays (`data-playing`); at rest they're
 * inert wrappers.
 */

/** Escapes text for use as element content (never in an attribute). */
function escapeHtml(text: string): string {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;");
}

/** Spaces are where lines may break; everything else sits in a word. */
const isSpace = (glyph: string): boolean =>
  glyph === " " || glyph === "\t" || glyph === "\n";

/** Server markup: words of glyphs, with spaces between them. */
function glyphsHtml(text: string): string {
  let html = "";
  let word = "";
  for (const glyph of textUnits(text)) {
    if (isSpace(glyph)) {
      if (word) html += `<span data-word>${word}</span>`;
      word = "";
      html += `<span data-glyph data-space>${escapeHtml(glyph)}</span>`;
    } else {
      word += `<span data-glyph>${escapeHtml(glyph)}</span>`;
    }
  }
  if (word) html += `<span data-word>${word}</span>`;
  return html;
}

function createGlyph(text: string): HTMLSpanElement {
  const span = document.createElement("span");
  span.setAttribute("data-glyph", "");
  if (isSpace(text)) span.setAttribute("data-space", "");
  span.textContent = text;
  return span;
}

const spaceNode = (node: HTMLElement): boolean =>
  node.hasAttribute("data-space");

/**
 * Lay glyphs out as words, the same structure the server renders, each
 * glyph in a slot: room above and below its line that fades it out while a
 * change plays, taking no space of its own. A glyph that travels turns its
 * slot's fade off (`data-travel`) only when it moves to another line; one
 * that slides along its line keeps the fade and gets room beside it for the
 * slide (`--reach`).
 */
function layOut(layer: HTMLElement, nodes: HTMLElement[]): void {
  const parts: HTMLElement[] = [];
  let word: HTMLElement | null = null;
  for (const node of nodes) {
    if (spaceNode(node)) {
      word = null;
      parts.push(node);
      continue;
    }
    if (!word) {
      word = document.createElement("span");
      word.setAttribute("data-word", "");
      parts.push(word);
    }
    const slot = document.createElement("span");
    slot.className = "text-morph-slot";
    slot.append(node);
    word.append(slot);
  }
  layer.replaceChildren(...parts);
}

type VisualState = {
  rect: DOMRect;
  opacity: number;
  scale: string;
  rotate: string;
  filter: string;
};

function visualState(node: HTMLElement): VisualState {
  const style = getComputedStyle(node);
  return {
    rect: node.getBoundingClientRect(),
    opacity: Number(style.opacity),
    scale: style.scale === "none" ? "1" : style.scale,
    rotate: style.rotate === "none" ? "0deg" : style.rotate,
    filter: style.filter === "none" ? "blur(0px)" : style.filter,
  };
}

/**
 * Stagger delays for the glyphs that change. `each`: every successive glyph
 * `ms` later. `spread` (Scritto's sweep): delay from where the glyph sits,
 * across `ms` over the changed stretch only, so a one-digit change in a long
 * number isn't left waiting, and a glyph leaving and its replacement in the
 * same spot cross over together. Positions count from the start of the
 * line in reading order. The sweep spans `ms` less one glyph's step, as
 * Scritto's ladder does, so two glyphs are half of it apart, not all of it.
 */
function staggerDelays(
  o: TextMorphOptions,
  entering: number[],
  leaving: number[],
): { entering: number[]; leaving: number[] } {
  if (o.stagger.mode === "each") {
    return {
      entering: entering.map((_, k) => k * o.stagger.ms),
      leaving: leaving.map((_, k) => k * o.stagger.ms),
    };
  }
  const all = [...entering, ...leaving];
  const min = Math.min(...all);
  const span = Math.max(...all) - min;
  const sweep = (count: number) => (left: number) =>
    span > 0
      ? (((o.stagger.ms * Math.max(count - 1, 0)) / count) * (left - min)) /
        span
      : 0;
  return {
    entering: entering.map(sweep(entering.length)),
    leaving: leaving.map(sweep(leaving.length)),
  };
}

/**
 * Transform keyframe for a glyph away from home: `offset` is 1 below the
 * line, -1 above. Morph letters scale in place; morph digits roll whole
 * lines (`line` is the line height in px).
 */
function awayState(
  o: TextMorphOptions,
  kind: GlyphKind,
  offset: 1 | -1,
  line: number,
): Keyframe {
  if (o.mode === "roll") {
    return {
      translate: `0 ${offset * o.roll.distance}em`,
      scale: String(o.roll.scale),
      rotate: `${o.roll.rotate}deg`,
    };
  }
  if (kind === "number") {
    return {
      translate: `0 ${offset * o.morph.digits.distance * line}px`,
      scale: "1",
      rotate: "0deg",
    };
  }
  return { translate: "0 0", scale: String(o.morph.scale), rotate: "0deg" };
}

/**
 * Morph mode, one-word values (torph): a run of this many replaced glyphs,
 * with no survivor inside, is swapped as one shape rather than glyph by
 * glyph. It recedes further, to GROUP_SCALE about its own centre, and its
 * fades take these shares of the movement's duration.
 */
const GROUP_MIN = 6;
const GROUP_SCALE = 0.8;
const GROUP_FADE_IN = 0.35;
const GROUP_FADE_OUT = 0.45;

/** Its scale's pivot, written only when it changes. */
function setOrigin(node: HTMLElement, origin: string): void {
  if (node.style.transformOrigin !== origin) {
    node.style.transformOrigin = origin;
  }
}

/** How a glyph arriving or leaving as part of a shape scales. */
type Shape = { origin: string; group: boolean };

/** Scale each member about the centre of the whole run. */
function shapeRun(
  shapes: Map<HTMLElement, Shape>,
  members: { node: HTMLElement; rect: DOMRect }[],
  group: boolean,
): void {
  const left = Math.min(...members.map((m) => m.rect.left));
  const right = Math.max(...members.map((m) => m.rect.right));
  const top = Math.min(...members.map((m) => m.rect.top));
  const bottom = Math.max(...members.map((m) => m.rect.bottom));
  for (const { node, rect } of members) {
    shapes.set(node, {
      origin: `${(left + right) / 2 - rect.left}px ${(top + bottom) / 2 - rect.top}px`,
      group,
    });
  }
}

/**
 * The runs of changed glyphs (arriving, or leaving) to shape: whole words,
 * or runs of at least GROUP_MIN between survivors.
 */
function shapeRuns(
  nodes: HTMLElement[],
  changed: (i: number) => boolean,
  byWords: boolean,
): number[][] {
  const runs: number[][] = [];
  let run: number[] = [];
  let whole = true;
  const flush = (): void => {
    if (byWords ? whole && run.length > 0 : run.length >= GROUP_MIN) {
      runs.push(run);
    }
    run = [];
    whole = true;
  };
  nodes.forEach((node, i) => {
    if (spaceNode(node)) return flush();
    if (changed(i)) run.push(i);
    else if (byWords) whole = false;
    else flush();
  });
  flush();
  return runs;
}

/** Fade timings for a glyph of this kind. */
function fadesFor(
  o: TextMorphOptions,
  kind: GlyphKind,
): {
  fadeIn: TextMorphOptions["fadeIn"];
  fadeOut: TextMorphOptions["fadeOut"];
} {
  if (o.mode === "morph" && kind === "number") {
    return {
      fadeIn: { ...o.morph.digits.fadeIn, delay: 0 },
      fadeOut: o.morph.digits.fadeOut,
    };
  }
  return { fadeIn: o.fadeIn, fadeOut: o.fadeOut };
}
/** Share of its fade a glyph interrupted mid-fade takes to finish. */
const CATCH_UP = 0.25;
const HOME: Keyframe = { translate: "0 0", scale: "1", rotate: "0deg" };

/**
 * How a change plays: in full, as a crossfade only (the reader prefers
 * reduced motion: remove the movement, keep the change visible), or not at
 * all (disabled, or nobody can see it).
 */
type Playback = "full" | "reduced" | "none";

/** The options with nothing that moves, scales, tilts or blurs. */
function stillOptions(o: TextMorphOptions): TextMorphOptions {
  return {
    ...o,
    stagger: { ...o.stagger, ms: 0 },
    roll: { distance: 0, scale: 1, rotate: 0 },
    morph: { ...o.morph, scale: 1, digits: { ...o.morph.digits, distance: 0 } },
    blur: 0,
  };
}

/** How far `a`'s centre sits from `b`'s (scale and tilt pivot on centres). */
function centreDelta(a: DOMRect, b: DOMRect): [number, number] {
  return [
    a.left + a.width / 2 - (b.left + b.width / 2),
    a.top + a.height / 2 - (b.top + b.height / 2),
  ];
}

const CLIPS = /auto|scroll|hidden|clip/;

/** Whether an element cuts off what overflows it (a scroller, a clip). */
const clips = (style: CSSStyleDeclaration): boolean =>
  CLIPS.test(style.overflowX) || CLIPS.test(style.overflowY);

/**
 * Whether a change here would be seen: rendered, and within the viewport
 * and every ancestor that clips it (Scritto's), so a label scrolled out of
 * view inside a scrolling panel swaps without animating.
 */
function isOnScreen(el: HTMLElement): boolean {
  if (el.checkVisibility && !el.checkVisibility()) return false;
  let top = 0;
  let left = 0;
  let bottom = window.innerHeight;
  let right = window.innerWidth;
  for (let node = el.parentElement; node; node = node.parentElement) {
    if (!clips(getComputedStyle(node))) continue;
    const box = node.getBoundingClientRect();
    top = Math.max(top, box.top);
    left = Math.max(left, box.left);
    bottom = Math.min(bottom, box.bottom);
    right = Math.min(right, box.right);
  }
  const rect = el.getBoundingClientRect();
  return (
    rect.bottom > top &&
    rect.right > left &&
    rect.top < bottom &&
    rect.left < right
  );
}

/** The edge fade's ramp, and how far past the box edge it ends (em). */
const EDGE_RAMP = 0.3;
const EDGE_SLACK = 0.4;
/** Room around a ghost for its blur, tilt and scale (em). */
const INK_MARGIN = 0.3;
/** A ghost slot's room beside its glyph (em), for tilt, scale and blur. */
const SLOT_PAD_X = 0.5;
/** Its room above and below, which it fades across (em). */
const SLOT_PAD_Y = 0.3;

type Side = "start" | "end";

/**
 * Whether a box shows an edge: a background, a side border, a shadow (a
 * ring, a shadow-drawn outline) or a frosted backdrop.
 */
function showsEdge(style: CSSStyleDeclaration): boolean {
  return (
    style.backgroundImage !== "none" ||
    (style.backgroundColor !== "rgba(0, 0, 0, 0)" &&
      style.backgroundColor !== "transparent") ||
    parseFloat(style.borderLeftWidth) > 0 ||
    parseFloat(style.borderRightWidth) > 0 ||
    style.boxShadow !== "none" ||
    (style.backdropFilter !== "" && style.backdropFilter !== "none")
  );
}

/** Whether a pseudo-element draws a surface for its box (a button's fill). */
function pseudoShowsEdge(
  node: Element,
  which: "::before" | "::after",
): boolean {
  const style = getComputedStyle(node, which);
  return (
    style.content !== "none" && style.content !== "normal" && showsEdge(style)
  );
}

/**
 * The inner edges of what a reader sees as holding the value (Scritto's
 * bounds): the nearest ancestor that shows an edge, itself or through a
 * pseudo-element (our Button paints its fill on `::before`), or clips; else
 * the viewport. A plain block around it has no edge to see.
 */
function visibleBounds(el: HTMLElement): { left: number; right: number } {
  for (let node = el.parentElement; node; node = node.parentElement) {
    const style = getComputedStyle(node);
    if (
      showsEdge(style) ||
      clips(style) ||
      pseudoShowsEdge(node, "::before") ||
      pseudoShowsEdge(node, "::after")
    ) {
      const box = node.getBoundingClientRect();
      return {
        left: box.left + parseFloat(style.borderLeftWidth),
        right: box.right - parseFloat(style.borderRightWidth),
      };
    }
  }
  return { left: 0, right: window.innerWidth };
}

/**
 * Whether old ink escaping the box on this side would land on something:
 * a neighbour on the line, or past the edge a reader sees holding the value
 * (a pill, a card, a clipping wrapper), whose position it returns. With room
 * around it, ink is left to dissolve on its own opacity. Reads the final
 * layout.
 */
function inkEscapes(
  root: HTMLElement,
  side: Side,
  inkEdge: number,
): false | "neighbour" | number {
  let el: Element = root;
  for (let depth = 0; depth < 8; depth++) {
    // `side` is physical (start: left, end: right); in right-to-left text
    // the next sibling sits to the left.
    const rtl =
      el.parentElement !== null &&
      getComputedStyle(el.parentElement).direction === "rtl";
    const toRight = (side === "end") !== rtl;
    let sibling = toRight ? el.nextSibling : el.previousSibling;
    while (sibling) {
      const visible =
        sibling instanceof Element
          ? sibling.getBoundingClientRect().width >= 1
          : Boolean(sibling.textContent?.trim());
      if (visible) return "neighbour";
      sibling = toRight ? sibling.nextSibling : sibling.previousSibling;
    }
    // Neighbours share the line up to the first block around it.
    const parent = el.parentElement;
    if (!parent) break;
    const { display } = getComputedStyle(parent);
    if (!display.startsWith("inline") && display !== "contents") break;
    el = parent;
  }
  // Past the container's edge: the edge itself, where the fade belongs.
  const bounds = visibleBounds(root);
  if (side === "end")
    return inkEdge > bounds.right + 0.5 ? bounds.right : false;
  return inkEdge < bounds.left - 0.5 ? bounds.left : false;
}

/**
 * How many lines an inline element's text runs over: rows, not the
 * fragments `getClientRects` reports (a line can come back in pieces, split
 * around a space or a line break).
 */
function lineCount(el: HTMLElement): number {
  const tops: number[] = [];
  for (const rect of el.getClientRects()) {
    if (!tops.some((top) => Math.abs(top - rect.top) < 1)) tops.push(rect.top);
  }
  return tops.length;
}

/** The height to set to make an element this tall, by its box-sizing. */
function heightOf(style: CSSStyleDeclaration, rect: DOMRect): number {
  if (style.boxSizing === "border-box") return rect.height;
  return (
    rect.height -
    parseFloat(style.paddingTop) -
    parseFloat(style.paddingBottom) -
    parseFloat(style.borderTopWidth) -
    parseFloat(style.borderBottomWidth)
  );
}

/** A box's width as its `width` property counts it, from its rect. */
function widthOf(style: CSSStyleDeclaration, rect: DOMRect): number {
  if (style.boxSizing === "border-box") return rect.width;
  return (
    rect.width -
    parseFloat(style.paddingLeft) -
    parseFloat(style.paddingRight) -
    parseFloat(style.borderLeftWidth) -
    parseFloat(style.borderRightWidth)
  );
}

const px = (el: HTMLElement, name: string): number =>
  parseFloat(el.style.getPropertyValue(name)) || 0;

/** A ghost slot at x/y (its glyph's box, layer coordinates). */
function placeSlot(slot: HTMLElement, x: number, y: number): void {
  slot.style.setProperty("--x", `${x}px`);
  slot.style.setProperty("--y", `${y}px`);
}

/** Lift the edge fade (its band animation already cancelled). */
function disarm(ghostLayer: HTMLElement): void {
  ghostLayer.style.removeProperty("--text-morph-edge");
  delete ghostLayer.dataset.armed;
}

/**
 * Fold the ghost layer away, its animations already cancelled. (Asking for
 * them would flush style, which a change avoids after moving nodes.)
 */
function resetLayer(ghostLayer: HTMLElement): void {
  disarm(ghostLayer);
  ghostLayer.style.width = "";
  ghostLayer.style.height = "";
}

/**
 * A change runs in phases, yielding between them: reads, then writes, then
 * reads again. Every label that changes in the same update is stepped
 * through the phases together, so all of them read before any of them
 * writes. Reading after the DOM changes forces the browser to restyle, and
 * on a page with complex `:has()` selectors each such restyle can cover the
 * whole document; batched, a set of changes costs one instead of several
 * per label.
 */
type MorphSteps = Generator<void, Animation[], void>;

type MorphJob = {
  root: HTMLElement;
  steps: MorphSteps;
  done: (started: Animation[]) => void;
};

const queue: MorphJob[] = [];

/**
 * Where each label was last seen pinned as it resized (0 start, 1 end, 0.5
 * centred), from how far each edge travelled: what a roll run's travel is
 * measured against (Scritto's anchor).
 */
const anchors = new WeakMap<HTMLElement, number>();

/** Until a label has resized, a guess from its alignment. */
function anchorHint(style: CSSStyleDeclaration): number {
  const rtl = style.direction === "rtl";
  switch (style.textAlign) {
    case "center":
      return 0.5;
    case "end":
      return 1;
    case "right":
      return rtl ? 0 : 1;
    case "left":
      return rtl ? 1 : 0;
    default:
      return 0;
  }
}

/** A leaving glyph's animations, so a change that brings it back can stop them. */
const ghostAnimations = new WeakMap<HTMLElement, Animation[]>();

/** Tags a label's current resize, so an older one can't release it. */
let sizings = 0;

function flushMorphs(): void {
  let active = queue.splice(0);
  while (active.length > 0) {
    active = active.filter((job) => {
      const step = job.steps.next();
      if (!step.done) return true;
      job.done(step.value);
      return false;
    });
  }
}

/** Run a change with the others from this update, before the next paint. */
function scheduleMorph(job: MorphJob): void {
  // A second change to the same label before the batch runs goes after it.
  if (queue.some((queued) => queued.root === job.root)) flushMorphs();
  queue.push(job);
  if (queue.length === 1) queueMicrotask(flushMorphs);
}

function* morphTo(
  root: HTMLElement,
  stage: HTMLElement,
  glyphLayer: HTMLElement,
  ghostAnchor: HTMLElement,
  ghostLayer: HTMLElement,
  value: string,
  options: TextMorphOptions,
  place: { decimal: string; caret: number | undefined },
  playback: () => Playback,
): MorphSteps {
  // Everything this change starts, so the caller can tell when it's over.
  const started: Animation[] = [];
  const run = (
    el: Element,
    keyframes: Keyframe[],
    timing: KeyframeAnimationOptions,
  ): Animation => {
    const animation = el.animate(keyframes, timing);
    started.push(animation);
    return animation;
  };
  if (!root.isConnected) return started;
  const old = Array.from(
    glyphLayer.querySelectorAll<HTMLElement>("[data-glyph]"),
  );
  const next = textUnits(value);

  // 1. Read: where everything is on screen right now.
  const play = playback();
  const reduced = play === "reduced";
  const o = reduced ? stillOptions(options) : options;
  const rootBefore = root.getBoundingClientRect();
  const styleBefore = getComputedStyle(root);
  const startBefore = parseFloat(styleBefore.marginInlineStart) || 0;
  const linesBefore = lineCount(glyphLayer);
  // A label laid out as a box (a block, an inline-block, a flex item) can
  // take a height, so a change that adds or removes a line eases it, as
  // torph's inline-block root does. An inline label's height is its lines'.
  const boxed = styleBefore.display !== "inline";
  const heightBefore = heightOf(styleBefore, rootBefore);
  const originBefore = ghostAnchor.getBoundingClientRect();
  const before = new Map(old.map((node) => [node, visualState(node)]));
  // Ghosts still leaving; ones already gone are cleared in step 4.
  const gone: HTMLElement[] = [];
  const slots = (Array.from(ghostLayer.children) as HTMLElement[]).filter(
    (slot) => {
      if (slot.dataset.gone === undefined) return true;
      gone.push(slot);
      return false;
    },
  );
  const ghosts = slots.flatMap((slot) => {
    const node = slot.firstElementChild;
    return node instanceof HTMLElement
      ? [{ slot, node, drawn: visualState(node) }]
      : [];
  });

  // 2. New glyph list.
  const match = matchText(
    o.mode,
    old.map((node) => node.textContent ?? ""),
    next,
    {
      numbers: o.numbers,
      decimal: place.decimal,
      trend: o.trend === "up" ? 1 : o.trend === "down" ? -1 : 0,
      anchor: anchors.get(root) ?? anchorHint(styleBefore),
      caret:
        place.caret === undefined ? undefined : caretUnits(next, place.caret),
    },
  );
  const used = new Set(match.kept);
  const kept = match.kept.map((from) => (from === -1 ? null : old[from]));
  const leaving = old.flatMap((node, i) =>
    used.has(i) || spaceNode(node)
      ? []
      : [{ node, kind: match.oldKinds[i], index: i }],
  );
  const nodes = next.map((glyph, i) => kept[i] ?? createGlyph(glyph));
  yield;

  // 2. Write: stop what's running (a style change, not a structural one).
  const slotOf = (node: HTMLElement): HTMLElement[] => {
    const slot = node.parentElement;
    return slot?.classList.contains("text-morph-slot") ? [slot] : [];
  };
  // A kept glyph's roll in progress, kept to carry on (step 8) if its place
  // doesn't change: restarted from where it's drawn, a held key sent every
  // digit still settling off again on a fresh curve each press, lurching
  // forward, and one within half a pixel of home snapped there.
  const rolling = new Map<
    HTMLElement,
    { keyframes: Keyframe[]; timing: EffectTiming; time: CSSNumberish | null }[]
  >();
  nodes.forEach((node, i) => {
    if (!kept[i]) return;
    const rolls = node.getAnimations().flatMap((animation) => {
      const effect = animation.effect as KeyframeEffect | null;
      const keyframes = effect?.getKeyframes() ?? [];
      if (!effect || !keyframes.some((k) => "translate" in k)) return [];
      return [
        {
          keyframes,
          timing: effect.getTiming(),
          time: animation.currentTime,
        },
      ];
    });
    if (rolls.length > 0) rolling.set(node, rolls);
  });
  const running = [
    ...nodes,
    ...leaving.map((l) => l.node),
    ...nodes.flatMap(slotOf),
    ...leaving.flatMap((l) => slotOf(l.node)),
    stage,
    root,
    ghostLayer,
  ];
  for (const el of running) {
    for (const animation of el.getAnimations()) animation.cancel();
  }
  yield;

  // 3. Read: where leaving glyphs sit in the layout, with nothing moving
  // them.
  const homes = new Map(
    leaving.map(({ node }) => [node, node.getBoundingClientRect()]),
  );
  // And which line each kept glyph sits on, whatever a roll in progress is
  // drawing it at.
  const keptHomes = new Map(
    nodes.flatMap((node, i) =>
      kept[i] && !spaceNode(node) ? [[node, node.getBoundingClientRect()]] : [],
    ),
  );
  yield;

  // 4. Write: the new glyphs, back to flowing inline, the resting layout.
  // Every structural change happens here, so the batch restyles once.
  layOut(glyphLayer, nodes);
  // Free to wrap again, so step 5 sees how the new value falls.
  delete root.dataset.sizing;
  stage.style.left = "";
  for (const slot of gone) slot.remove();
  // The slots fade from step 8 on, while this change plays.
  delete glyphLayer.dataset.playing;
  if (play === "none") {
    // Swapped without a change to watch: an earlier change's ghosts and
    // edge fade go too (their animations were stopped in step 2).
    ghostLayer.replaceChildren();
    resetLayer(ghostLayer);
    return started;
  }
  // Leaving glyphs move into slots in the ghost layer (placed in step 8).
  const newSlots = leaving.flatMap(({ node, kind, index }) => {
    const home = homes.get(node);
    if (!home) return [];
    const slot = document.createElement("span");
    slot.className = "text-morph-ghost";
    slot.style.setProperty("--w", `${home.width}px`);
    slot.style.setProperty("--h", `${home.height}px`);
    slot.append(node);
    ghostLayer.append(slot);
    return [{ slot, node, kind, home, index }];
  });
  yield;

  // 5. Read: a change that stays on one line is animated as a box; one that
  // wraps keeps its lines as they fall. An empty value has no line box at
  // all; it counts as one line.
  // `box` below means that: the label's space eases as one box.
  const oneLine = lineCount(glyphLayer) <= 1;
  const box = !reduced && linesBefore <= 1 && oneLine;
  // And the rest of the final layout, with the start margin the author set.
  const rootAfter = root.getBoundingClientRect();
  const glyphsAfter = glyphLayer.getBoundingClientRect();
  const styleAfter = getComputedStyle(root);
  const startAfter = parseFloat(styleAfter.marginInlineStart) || 0;
  const heightAfter = heightOf(styleAfter, rootAfter);
  const reheights =
    boxed && !reduced && Math.abs(heightAfter - heightBefore) > 0.5;
  const origin = ghostAnchor.getBoundingClientRect();
  // Reading direction, for the stagger's sweep.
  const rtl = getComputedStyle(glyphLayer).direction === "rtl";
  const after = nodes.map((node) => node.getBoundingClientRect());
  const em = parseFloat(getComputedStyle(root).fontSize) || 16;

  // Glyphs that travel further than their slot's room go unmasked.
  // A kept glyph moving to another line (wrapped text) goes unmasked, or
  // its slot would hide it on the way. One sliding along its line keeps the
  // fade, since it may be mid-roll and meant to fade back in, and its slot
  // gets room beside it for the slide.
  const changesLine: HTMLElement[] = [];
  const reach: [HTMLElement, number][] = [];
  nodes.forEach((node, i) => {
    const was = kept[i] ? before.get(node) : undefined;
    const home = keptHomes.get(node);
    if (!was || !home) return;
    if (Math.abs(home.top - after[i].top) > SLOT_PAD_Y * em) {
      changesLine.push(node);
      return;
    }
    const slide = Math.abs(centreDelta(was.rect, after[i])[0]);
    if (slide > 0.5) reach.push([node, Math.ceil(slide)]);
  });
  const letter = nodes.findIndex((node) => !spaceNode(node));
  const line = letter === -1 ? em * 1.2 : after[letter].height;

  // Which way glyphs roll (`trend`, read off the value when `auto`): a rise
  // brings new glyphs up from below and sends old ones up and away. Morph's
  // `down` is torph's: digits fall in from above and leave downward while a
  // number's other marks arrive from below, so each reads as its own event.
  const rise = match.trend === 1;
  const marksRise = o.mode === "morph" && o.trend === "down";
  const arriveFor = (glyph: string): 1 | -1 =>
    rise || (marksRise && !isDigit(glyph)) ? 1 : -1;
  const away = rise ? -1 : 1;

  // A new glyph whose text is still leaving from where it lands (a quick
  // 5 -> 6 -> 5) takes that ghost back rather than crossing it: the ghost
  // turns around from wherever it's drawn, like a kept glyph. Where a ghost
  // sat in the layout is its slot's place, which holds still on screen.
  // Only a ghost on the side new glyphs arrive from turns around: in roll,
  // 5 -> 6 -> 5 sent the old 5 up and brings the new one down from above,
  // so it comes back the way arrivals do; in morph, digits always fall, and
  // bringing a falling ghost back up ran against the flow (sweeping a chart
  // reversed 19 digits mid-fall, torph none).
  const reclaimed: { index: number; slot: HTMLElement; node: HTMLElement }[] =
    [];
  const claimed = new Set<HTMLElement>();
  const comesBackWithArrivals = (
    drawn: DOMRect,
    target: DOMRect,
    glyph: string,
  ): boolean => {
    const dy = centreDelta(drawn, target)[1];
    return Math.abs(dy) <= 1 || Math.sign(dy) === arriveFor(glyph);
  };
  nodes.forEach((node, i) => {
    if (kept[i] || spaceNode(node)) return;
    const target = after[i];
    const ghost = ghosts.find(
      (g) =>
        !claimed.has(g.slot) &&
        g.node.textContent === next[i] &&
        Math.abs(originBefore.left + px(g.slot, "--x") - target.left) <
          target.width / 2 &&
        Math.abs(originBefore.top + px(g.slot, "--y") - target.top) <
          SLOT_PAD_Y * em &&
        // Still drawn within the label: one carried out past its edge (with
        // a neighbour, toward a pinned edge) keeps leaving under the edge
        // fade, since the live glyphs have none to hide it on its way back.
        g.drawn.rect.left >= rootAfter.left - 0.5 &&
        g.drawn.rect.right <= rootAfter.right + 0.5 &&
        comesBackWithArrivals(g.drawn.rect, target, next[i]),
    );
    if (!ghost) return;
    claimed.add(ghost.slot);
    reclaimed.push({ index: i, slot: ghost.slot, node: ghost.node });
    before.set(ghost.node, ghost.drawn);
    const slide = Math.abs(centreDelta(ghost.drawn.rect, target)[0]);
    if (slide > 0.5) reach.push([ghost.node, Math.ceil(slide)]);
  });
  const staying = ghosts.filter((g) => !claimed.has(g.slot));
  const reclaimedAt = new Map(reclaimed.map((r) => [r.index, r.node]));

  // What arrives or leaves travels with its nearest surviving neighbour
  // (torph's anchoring), looking before it first when arriving and after it
  // first when leaving. Its slot takes the trip and the glyph its own
  // entrance inside it (torph's slot and mover), so a digit rolls within a
  // number that moves line, where adding the two up cancelled them (a
  // morph digit rolls exactly one line). Morph anchors everything; roll
  // only digits, to the rest of their own number, and only across lines:
  // its glyphs still roll in place on their line (a number that resizes
  // doesn't drag them after its `$`), and a number that moves to another
  // line takes its digits with it.
  //
  // Morph also scales a whole word arriving or leaving about its own
  // centre, as one shape; in a one-word value, only a run of GROUP_MIN or
  // more replaced glyphs, further and faster.
  const shaping = o.mode === "morph" && !reduced;
  // How far each survivor moved in the layout, from its old place to its
  // final one. The layout, not where it's drawn (torph measures with
  // transforms taken out): a digit still falling in is drawn above its
  // place, and anchoring the next one to that stacked each fall on the
  // last, so typing fast brought digits in from ever higher.
  const startsAt = new Map<number, [number, number]>();
  nodes.forEach((node, i) => {
    const home = kept[i] && !spaceNode(node) ? keptHomes.get(node) : null;
    if (home) startsAt.set(i, centreDelta(home, after[i]));
  });
  /** Where a glyph may find its neighbour: anywhere, or its own number. */
  const scope = (kinds: GlyphKind[], i: number): [number, number] | null => {
    if (reduced) return null;
    if (o.mode === "morph") return [0, kinds.length - 1];
    if (kinds[i] !== "number") return null;
    let first = i;
    let last = i;
    while (first > 0 && kinds[first - 1] === "number") first--;
    while (last < kinds.length - 1 && kinds[last + 1] === "number") last++;
    return [first, last];
  };
  const nearest = (
    index: number,
    [first, last]: [number, number],
    offsetAt: (i: number) => [number, number] | undefined,
    forwardFirst: boolean,
  ): [number, number] | undefined => {
    const scan = (step: 1 | -1): [number, number] | undefined => {
      for (let j = index + step; j >= first && j <= last; j += step) {
        const offset = offsetAt(j);
        if (offset) return offset;
      }
      return undefined;
    };
    const [one, two]: [1 | -1, 1 | -1] = forwardFirst ? [1, -1] : [-1, 1];
    return scan(one) ?? scan(two);
  };
  // A trip to another line, not a centred value recentring by half a line
  // as its line count changes.
  const crossesLines = ([, dy]: [number, number]): boolean =>
    Math.abs(dy) > line * 0.75;
  const travels = (trip: [number, number]): boolean =>
    o.mode === "morph" || crossesLines(trip);
  const isArriving = (i: number): boolean =>
    !kept[i] && !reclaimedAt.has(i) && !spaceNode(nodes[i]);
  const shapes = new Map<HTMLElement, Shape>();
  if (shaping) {
    // Whole words of letters (by words), and runs of GROUP_MIN or more
    // replaced glyphs, digits included: torph splits numbers glyph by glyph
    // either way, so `$12,345,678` → `$99` shrinks its old digits in place
    // rather than sending them after the `$`.
    const shapeAll = (
      glyphs: HTMLElement[],
      changed: (i: number) => boolean,
      kinds: GlyphKind[],
      rectOf: (i: number) => DOMRect | undefined,
    ): void => {
      const add = (runs: number[][], group: boolean): void => {
        for (const run of runs) {
          const members = run.flatMap((i) => {
            const rect = rectOf(i);
            return rect ? [{ node: glyphs[i], rect }] : [];
          });
          if (members.length > 0) shapeRun(shapes, members, group);
        }
      };
      if (!match.byWords) return add(shapeRuns(glyphs, changed, false), true);
      const of = (kind: GlyphKind) => (i: number) =>
        changed(i) && kinds[i] === kind;
      add(shapeRuns(glyphs, of("text"), true), false);
      add(shapeRuns(glyphs, of("number"), false), true);
    };
    shapeAll(nodes, isArriving, match.nextKinds, (i) => after[i]);
    const leavingAt = new Set(leaving.map((l) => l.index));
    shapeAll(
      old,
      (i) => leavingAt.has(i),
      match.oldKinds,
      (i) => homes.get(old[i]),
    );
  }
  // A neighbour is one on the same line: in wrapped text the glyph before
  // a line's first is at the end of the line above, and travelling with it
  // would carry the glyph off the start of its own line (torph never wraps).
  const sameLine = (a: DOMRect | undefined, b: DOMRect | undefined): boolean =>
    a !== undefined && b !== undefined && Math.abs(a.top - b.top) < line / 2;
  // An arriving glyph starts where its neighbour starts; a shape swapped
  // as one doesn't travel.
  const arrivals = new Map<number, [number, number]>();
  nodes.forEach((node, i) => {
    const range = scope(match.nextKinds, i);
    if (!range || !isArriving(i) || shapes.get(node)?.group) return;
    const shift = nearest(
      i,
      range,
      (j) => (sameLine(after[j], after[i]) ? startsAt.get(j) : undefined),
      false,
    );
    if (shift && travels(shift)) arrivals.set(i, shift);
  });
  // A leaving glyph goes where its neighbour goes.
  const newIndexOf = new Map(
    match.kept.flatMap((from, to) => (from === -1 ? [] : [[from, to]])),
  );
  const departures = new Map<HTMLElement, [number, number]>();
  for (const { node, index } of newSlots) {
    const range = scope(match.oldKinds, index);
    if (!range || shapes.get(node)?.group) continue;
    const start = nearest(
      index,
      range,
      (j) => {
        const to = newIndexOf.get(j);
        if (to === undefined) return undefined;
        return sameLine(keptHomes.get(old[j]), homes.get(node))
          ? startsAt.get(to)
          : undefined;
      },
      true,
    );
    if (start && travels(start)) departures.set(node, [-start[0], -start[1]]);
  }

  // Ghost coordinates start at the layer's place in the flow, which holds
  // still on screen for the whole change, so earlier ghosts shift by however
  // far it moved, and hold theirs (placed in step 8).
  const shiftX = originBefore.left - origin.left;
  const shiftY = originBefore.top - origin.top;

  // Edge fade (boxes only): the box before and after, and how far old ink
  // reaches past it, in layer coordinates.
  const boxStart = rootBefore.left - origin.left;
  const boxEnd = rootBefore.right - origin.left;
  const finalStart = rootAfter.left - origin.left;
  const finalEnd = rootAfter.right - origin.left;
  // And where leaving ink ends up when it travels with a neighbour: past an
  // edge that doesn't move (a right-pinned button's), carried out by the
  // survivor sliding toward it.
  const carried = leaving.flatMap(({ node }) => {
    const rect = before.get(node)?.rect;
    const trip = departures.get(node);
    return rect && trip
      ? [
          new DOMRect(
            rect.x + trip[0],
            rect.y + trip[1],
            rect.width,
            rect.height,
          ),
        ]
      : [];
  });
  const inkRects = [
    ...staying.map((g) => g.drawn.rect),
    ...leaving.flatMap(({ node }) => {
      const rect = before.get(node)?.rect;
      return rect ? [rect] : [];
    }),
    ...carried,
  ];
  // The glyph boxes decide whether ink sticks out; the room also covers
  // their blur and tilt.
  const glyphStart =
    Math.min(Infinity, ...inkRects.map((r) => r.left)) - origin.left;
  const glyphEnd =
    Math.max(-Infinity, ...inkRects.map((r) => r.right)) - origin.left;
  const wasArmed = ghostLayer.dataset.armed ?? "";
  // How each edge fades: not at all, following the box's edge (a neighbour
  // moves with it), or held at the container's edge (layer coordinates):
  // there only ink crossing it needs fading, and a band following the box
  // swept across letters still well inside (clearing a long value).
  const armed = (side: Side): false | "box" | number => {
    if (!box || o.edgeFade === "never" || inkRects.length === 0) return false;
    if (wasArmed.includes(side)) return "box";
    const travels =
      side === "start"
        ? Math.abs(boxStart - finalStart) > 0.5
        : Math.abs(boxEnd - finalEnd) > 0.5;
    const overhangs =
      side === "start"
        ? glyphStart < finalStart - 0.5
        : glyphEnd > finalEnd + 0.5;
    const carriedOut = carried.some((rect) =>
      side === "start"
        ? rect.left - origin.left < finalStart - 0.5
        : rect.right - origin.left > finalEnd + 0.5,
    );
    if (!(travels && overhangs) && !carriedOut) return false;
    if (o.edgeFade === "always") return "box";
    const escapes = inkEscapes(
      root,
      side,
      origin.left + (side === "start" ? glyphStart : glyphEnd),
    );
    if (escapes === false) return false;
    return escapes === "neighbour" ? "box" : escapes - origin.left;
  };
  const armStart = armed("start");
  const armEnd = armed("end");
  // The space it takes eases from what it visibly took (its box plus any
  // start margin still easing) to its new width.
  const from = box
    ? rootBefore.width + (startBefore - startAfter) - rootAfter.width
    : 0;
  const resizes = Math.abs(from) > 0.5;
  // A box eases its width, as torph's root does: its alignment inside holds
  // the glyphs where they end up, so nothing has to ride against it. An
  // inline label can't take a width, so it eases its start margin, and the
  // stage rides against the move; in centred text those two, each rounded
  // to layout units (1/64px) on its own, stepped the glyphs back and forth.
  const widthAfter = widthOf(styleAfter, rootAfter);
  // What the stage's percentages count: the label's content box.
  const contentAfter =
    rootAfter.width -
    parseFloat(styleAfter.paddingLeft) -
    parseFloat(styleAfter.paddingRight) -
    parseFloat(styleAfter.borderLeftWidth) -
    parseFloat(styleAfter.borderRightWidth);
  const sizeFrom = boxed
    ? { width: `${widthAfter + from}px` }
    : { marginInlineStart: `${startAfter + from}px` };
  const sizeTo = boxed
    ? { width: `${widthAfter}px` }
    : { marginInlineStart: `${startAfter}px` };
  yield;

  // 6. Write: the label at the start of its resize.
  const authorStart = root.style.marginInlineStart;
  const authorWidth = root.style.width;
  const authorHeight = root.style.height;
  if (resizes && boxed) {
    root.style.width = sizeFrom.width ?? "";
    // Its text sits at its start while it resizes (text-align in the CSS),
    // so the stage's ride alone places it, whichever way the width goes.
    root.dataset.sizing = "";
  }
  else if (resizes)
    root.style.marginInlineStart = sizeFrom.marginInlineStart ?? "";
  if (reheights) root.style.height = `${heightBefore}px`;
  yield;

  // 7. Read: where the label begins there, which the stage rides against.
  // Read even when it doesn't resize: a neighbour changing in the same
  // update may be easing its own space, which moves this label too.
  const rootAt0 =
    oneLine || reheights ? root.getBoundingClientRect() : rootAfter;
  const glyphsAt0 =
    oneLine || reheights ? glyphLayer.getBoundingClientRect() : glyphsAfter;
  // Which edge the label is pinned by, for the next change's run.
  if (resizes) {
    const leftTravel = Math.abs(rootAfter.left - rootAt0.left);
    const rightTravel = Math.abs(rootAfter.right - rootAt0.right);
    const rtl = styleAfter.direction === "rtl";
    const startTravel = rtl ? rightTravel : leftTravel;
    const travel = leftTravel + rightTravel;
    if (travel > 0.5) anchors.set(root, startTravel / travel);
  }
  yield;

  // 8. Write: everything else, attributes and styles only. Nothing below
  // reads layout or changes the DOM's structure.
  root.style.marginInlineStart = authorStart;
  root.style.width = authorWidth;
  root.style.height = authorHeight;
  glyphLayer.dataset.playing = "";
  // Reclaimed ghosts take their new glyph's place, which measured the same.
  for (const { index, slot, node } of reclaimed) {
    for (const animation of ghostAnimations.get(node) ?? []) {
      animation.cancel();
    }
    nodes[index].replaceWith(node);
    nodes[index] = node;
    kept[index] = node;
    slot.remove();
  }
  for (const { slot } of staying) {
    placeSlot(slot, px(slot, "--x") + shiftX, px(slot, "--y") + shiftY);
  }
  for (const node of changesLine) {
    node.parentElement?.setAttribute("data-travel", "");
  }
  for (const { slot, node } of newSlots) {
    const [dx, dy] = departures.get(node) ?? [0, 0];
    slot.style.setProperty("--trip-x", `${Math.ceil(Math.abs(dx))}px`);
    slot.style.setProperty("--trip-y", `${Math.ceil(Math.abs(dy))}px`);
  }
  for (const [node, px] of reach) {
    node.parentElement?.style.setProperty("--reach", `${px}px`);
  }

  // A glyph travelling to another line rolls the way it travels instead,
  // so a number that moves up scrolls up as it changes: rolling against
  // its trip, it would hold still on screen while its slot slid past.
  const rollWith = (
    trip: [number, number] | undefined,
    otherwise: 1 | -1,
  ): 1 | -1 =>
    trip && crossesLines(trip) ? (trip[1] > 0 ? 1 : -1) : otherwise;

  if (resizes) {
    const resize = { duration: o.width.duration, easing: o.width.easing };
    // While its space eases open, the value stays on one line. No-wrap
    // changes line breaking, not display, and the value sits on one line
    // either way.
    const sizing = String(++sizings);
    root.dataset.sizing = sizing;
    const ease = run(root, [sizeFrom, sizeTo], resize);
    const release = (): void => {
      if (root.dataset.sizing !== sizing) return;
      delete root.dataset.sizing;
      stage.style.left = "";
    };
    ease.finished.then(release, release);
  }

  // A box's height eases the same way, from what it was to what its new
  // lines take; the value's lines are laid out as they end up throughout.
  if (reheights) {
    run(
      root,
      [{ height: `${heightBefore}px` }, { height: `${heightAfter}px` }],
      { duration: o.width.duration, easing: o.width.easing },
    );
  }

  // The label moves while space eases (its own margin or height, a centred
  // or pinned container around it, or a neighbour changing in the same
  // update easing its space); ride the other way on the width's curve, so
  // the glyphs and ghosts hold the final places they were measured at.
  // A move that is just the label's own margin (all of it pinned at the
  // start or end, half of it centred) rides by the margin's exact value:
  // the measured one is rounded to layout units (1/64px), and the two
  // easing from values that far apart round apart frame to frame, so the
  // glyphs flickered a device pixel side to side (116 flips in one change
  // at 125% scaling).
  // A box rides by how far its glyphs moved (its alignment inside mostly
  // holds them); an inline label by how far it moved.
  const measuredX = boxed
    ? glyphsAfter.left - glyphsAt0.left
    : rootAfter.left - rootAt0.left;
  const ownX =
    resizes && !boxed
      ? [from, -from, from / 2, -from / 2].find(
          (x) => Math.abs(x - measuredX) < 0.05,
        )
      : undefined;
  // A box whose glyphs move with its width (all of the change pinned at the
  // end, half centred) rides by that share of its width as it eases, in
  // CSS: layout rounds the ride and the width it follows from the same
  // number each frame, where a ride animated beside the width rounded on
  // its own and stepped the glyphs back and forth.
  const share = boxed && resizes ? -measuredX / from : NaN;
  const follows = [-1, -0.5, 0.5, 1].find((f) => Math.abs(f - share) < 0.01);
  if (follows !== undefined) {
    stage.style.left = `calc(${follows} * (${contentAfter}px - 100%))`;
  }
  const rideX = follows !== undefined ? 0 : (ownX ?? measuredX);
  const rideY = boxed
    ? glyphsAfter.top - glyphsAt0.top
    : rootAfter.top - rootAt0.top;
  if (Math.abs(rideX) > 0.5 || Math.abs(rideY) > 0.5) {
    run(
      stage,
      [
        { left: `${rideX}px`, top: `${rideY}px` },
        { left: "0px", top: "0px" },
      ],
      { duration: o.width.duration, easing: o.width.easing },
    );
  }

  const motion = { duration: o.motion.duration, easing: o.motion.easing };
  // A filter animates only when there's blur to show: morph's default has
  // none, and a filter animation per glyph costs even when it changes
  // nothing.
  const blur = o.blur > 0 ? `blur(${o.blur}em)` : null;
  const fade = (opacity: number, filter: string | null): Keyframe =>
    filter === null ? { opacity } : { opacity, filter };
  const sharp = (filter: string | null): string | null =>
    filter === null ? null : "blur(0px)";
  const lineStart = (rect: DOMRect, box: DOMRect): number =>
    rtl ? box.right - rect.right : rect.left - box.left;
  const delays = staggerDelays(
    o,
    nodes.flatMap((node, i) =>
      kept[i] || spaceNode(node) ? [] : [lineStart(after[i], rootAfter)],
    ),
    leaving.map(({ node }) => {
      const rect = before.get(node)?.rect;
      return rect ? lineStart(rect, rootBefore) : 0;
    }),
  );

  // Shared glyphs slide from wherever they were, including mid-animation.
  let entering = 0;
  nodes.forEach((node, i) => {
    if (spaceNode(node)) return;
    const was = kept[i] ? before.get(node) : undefined;
    const kind = match.nextKinds[i];
    const { fadeIn } = fadesFor(o, kind);
    // Scale pivots on the glyph's own centre unless it arrives in a shape.
    const shape = shapes.get(node);
    setOrigin(node, shape?.origin ?? "");
    // A shape's glyph slides toward the shape's centre as it scales, out of
    // its slot, whose fade would cut it off; it doesn't roll, so it needs
    // no fade.
    if (shape?.group) node.parentElement?.setAttribute("data-travel", "");
    if (!was) {
      const delay = delays.entering[entering++];
      const awayFrame = shape?.group
        ? { translate: "0 0", scale: String(GROUP_SCALE), rotate: "0deg" }
        : awayState(
            o,
            kind,
            rollWith(arrivals.get(i), arriveFor(next[i])),
            line,
          );
      run(node, [awayFrame, HOME], {
        ...motion,
        delay,
        fill: "backwards",
      });
      const shift = arrivals.get(i);
      const slot = node.parentElement;
      if (shift && slot) {
        run(
          slot,
          [{ translate: `${shift[0]}px ${shift[1]}px` }, { translate: "0 0" }],
          { ...motion, delay, fill: "backwards" },
        );
      }
      const fadeTiming = shape?.group
        ? {
            duration: o.motion.duration * GROUP_FADE_IN,
            easing: "linear",
            delay,
          }
        : {
            duration: fadeIn.duration,
            easing: fadeIn.easing,
            delay: delay + fadeIn.delay,
          };
      run(node, [fade(0, blur), fade(1, sharp(blur))], {
        ...fadeTiming,
        fill: "backwards",
      });
      return;
    }
    // Under reduced motion a kept glyph takes its new place directly.
    const [dx, dy] = centreDelta(was.rect, after[i]);
    const home = keptHomes.get(node);
    const rolls = rolling.get(node);
    const stays =
      home !== undefined &&
      centreDelta(home, after[i]).every((d) => Math.abs(d) < 0.01);
    if (!reduced && rolls && stays) {
      // Its place holds: the roll it was on carries on where it was.
      for (const { keyframes, timing, time } of rolls) {
        run(node, keyframes, timing).currentTime = time;
      }
    } else if (
      !reduced &&
      (Math.abs(dx) > 0.5 ||
        Math.abs(dy) > 0.5 ||
        was.scale !== "1" ||
        was.rotate !== "0deg")
    ) {
      run(
        node,
        [
          {
            translate: `${dx}px ${dy}px`,
            scale: was.scale,
            rotate: was.rotate,
          },
          HOME,
        ],
        // Roll (Scritto): on the box's curve, not the roll's spring, or a
        // kept run outruns the box resizing around it.
        o.mode === "roll"
          ? { duration: o.width.duration, easing: o.width.easing }
          : motion,
      );
    }
    // Mid-fade (or mid-blur, from an earlier change) it catches up: the next
    // change means a newer value is what to read, so it finishes over a
    // quarter of its fade at most (50ms in morph) rather than hanging
    // half-faded. Restarting the whole fade left a run of quick changes (a
    // held key) crawling in; torph snaps it to full in one frame instead.
    const blurred = was.filter !== "blur(0px)" ? was.filter : null;
    if (was.opacity < 0.999 || blurred !== null) {
      const left = Math.max(1 - was.opacity, blurred !== null ? 0.25 : 0);
      run(node, [fade(was.opacity, blurred), fade(1, sharp(blurred))], {
        duration: fadeIn.duration * Math.min(left, CATCH_UP),
        easing: fadeIn.easing,
      });
    }
  });

  // Leaving glyphs sit at the place they had in the layout, and start from
  // wherever they were drawn.
  for (const { slot, home } of newSlots) {
    placeSlot(slot, home.left - origin.left, home.top - origin.top);
  }

  // Size the layer around every slot (a mask cuts whatever falls outside
  // its element) and, when the edge fade is armed, the band's reach.
  const allSlots = [
    ...staying.map((g) => g.slot),
    ...newSlots.map((s) => s.slot),
  ];
  if (allSlots.length === 0) {
    resetLayer(ghostLayer);
    return started;
  }
  const slack = EDGE_SLACK * em;
  const padX = SLOT_PAD_X * em;
  const padY = SLOT_PAD_Y * em;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const slot of allSlots) {
    const x = px(slot, "--x");
    const y = px(slot, "--y");
    const room = padX + px(slot, "--trip-x") + INK_MARGIN * em;
    const roomY = padY + px(slot, "--trip-y");
    minX = Math.min(minX, x - room);
    maxX = Math.max(maxX, x + px(slot, "--w") + room);
    minY = Math.min(minY, y - roomY);
    maxY = Math.max(maxY, y + px(slot, "--h") + roomY);
  }
  const fades = armStart !== false || armEnd !== false;
  if (fades) {
    minX = Math.min(minX, boxStart - slack, finalStart - slack);
    maxX = Math.max(maxX, boxEnd + slack, finalEnd + slack);
    if (typeof armStart === "number") minX = Math.min(minX, armStart);
    if (typeof armEnd === "number") maxX = Math.max(maxX, armEnd);
  }
  const ox = Math.floor(minX) - 1;
  const oy = Math.floor(minY) - 1;
  const layerWidth = Math.ceil(maxX) + 1 - ox;
  ghostLayer.style.setProperty("--ox", `${ox}px`);
  ghostLayer.style.setProperty("--oy", `${oy}px`);
  ghostLayer.style.width = `${layerWidth}px`;
  ghostLayer.style.height = `${Math.ceil(maxY) + 1 - oy}px`;

  // The edge fade: a band on each armed edge that follows the box edge on
  // the width's curve, ending a little past it, or holds at the container's.
  if (fades) {
    const ramp = EDGE_RAMP * em;
    const window = (start: number, end: number) => {
      const left =
        armStart === false
          ? 0
          : typeof armStart === "number"
            ? armStart - ox
            : start - slack - ox;
      const right =
        armEnd === false
          ? layerWidth
          : typeof armEnd === "number"
            ? armEnd - ox
            : end + slack - ox;
      return {
        maskPosition: `${left}px 0`,
        maskSize: `${right - left}px 100%`,
      };
    };
    ghostLayer.dataset.armed = `${armStart !== false ? "start " : ""}${armEnd !== false ? "end" : ""}`;
    ghostLayer.style.setProperty(
      "--text-morph-edge",
      `linear-gradient(to right, ${armStart !== false ? `transparent, #000 ${ramp}px` : "#000"}, ${
        armEnd !== false ? `#000 calc(100% - ${ramp}px), transparent` : "#000"
      })`,
    );
    run(ghostLayer, [window(boxStart, boxEnd), window(finalStart, finalEnd)], {
      duration: o.width.duration,
      easing: o.width.easing,
      fill: "forwards",
    });
  } else {
    disarm(ghostLayer);
  }

  newSlots.forEach(({ slot, node, kind, home }, i) => {
    const was = before.get(node);
    if (!was) return;
    const { fadeOut } = fadesFor(o, kind);
    const delay = delays.leaving[i];
    // Drawn where it was: the offset its animation had it at. Under
    // reduced motion it fades out there.
    const [dx, dy] = centreDelta(was.rect, home);
    const drawn: Keyframe = {
      translate: `${dx}px ${dy}px`,
      scale: was.scale,
      rotate: was.rotate,
    };
    // A shape's pivot applies only to a glyph at rest, or its first frame
    // would jump.
    const atRest = was.scale === "1" && was.rotate === "0deg";
    const shape = atRest ? shapes.get(node) : undefined;
    setOrigin(node, shape?.origin ?? "");
    if (shape?.group) slot.setAttribute("data-travel", "");
    const awayFrame = shape?.group
      ? { translate: "0 0", scale: String(GROUP_SCALE), rotate: "0deg" }
      : awayState(
          o,
          kind,
          // It leaves the way its trip goes.
          rollWith(departures.get(node), away),
          line,
        );
    const move = run(
      node,
      [drawn, reduced ? drawn : awayFrame],
      // Both: its starting place holds through the stagger delay too.
      { ...motion, delay, fill: "both" },
    );
    const trip = departures.get(node);
    if (trip) {
      run(
        slot,
        [{ translate: "0 0" }, { translate: `${trip[0]}px ${trip[1]}px` }],
        { ...motion, delay, fill: "both" },
      );
    }
    const blurred = was.filter !== "blur(0px)" ? was.filter : null;
    const out = run(
      node,
      [
        fade(was.opacity, blurred ?? (blur && "blur(0px)")),
        fade(0, blur ?? (blurred && "blur(0px)")),
      ],
      {
        ...(shape?.group
          ? { duration: o.motion.duration * GROUP_FADE_OUT, easing: "linear" }
          : { duration: fadeOut.duration, easing: fadeOut.easing }),
        delay,
        fill: "both",
      },
    );
    ghostAnimations.set(node, [move, out]);
    // A ghost that has left stays in place, invisible, until the last one
    // has: removing them together is one change to the DOM's structure (one
    // restyle) instead of one per ghost.
    const finish = (): void => {
      if (slot.parentNode !== ghostLayer) return;
      slot.dataset.gone = "";
      const slots = Array.from(ghostLayer.children) as HTMLElement[];
      if (slots.every((ghost) => ghost.dataset.gone !== undefined)) {
        for (const animation of ghostLayer.getAnimations()) animation.cancel();
        ghostLayer.replaceChildren();
        resetLayer(ghostLayer);
      }
    };
    // Cancelled by a later change, which already moved on without it.
    Promise.all([move.finished, out.finished]).then(finish, finish);
  });
  return started;
}

export type TextMorphProps = Omit<
  useRender.ComponentProps<"span">,
  "children" | "onAnimationStart" | "onAnimationEnd"
> & {
  /** The text. A number is formatted with `locale` and `decimals`. */
  value: string | number;
  /**
   * How changes animate. `mode` picks the defaults for everything else; any
   * field set here, nested ones included, overrides that mode's value.
   */
  options?: TextMorphOverrides;
  /**
   * Formats a number `value` and names the decimal separator numbers are
   * aligned on. Fixed rather than the browser's, so the server and the
   * browser render the same text.
   */
  locale?: string;
  /** Fraction digits for a number `value`. */
  decimals?: number;
  /** Swap the text without animating. */
  disabled?: boolean;
  /**
   * When the reader prefers reduced motion, crossfade in place: nothing
   * travels, scales, tilts, blurs or resizes.
   */
  respectReducedMotion?: boolean;
  /**
   * A change started animating. (These three are TextMorph's own events, not
   * the DOM's CSS animation events.)
   */
  onAnimationStart?: () => void;
  /**
   * A change finished, every glyph and the box settled. Fires right away
   * for a change that didn't animate (disabled, off screen). Each change
   * ends in exactly one of this and `onAnimationCancel`, unless the label
   * unmounts first.
   */
  onAnimationComplete?: () => void;
  /** A change was interrupted by the next one. */
  onAnimationCancel?: () => void;
  /**
   * For a field someone is typing in: where the caret sits in `value` after
   * the edit, as a string index (an input's `selectionStart`). Glyphs are
   * matched around it, so typing 1 in front of 20 inserts a digit instead of
   * renumbering the column. Leave it unset for values that change on their
   * own.
   */
  cursorIndex?: number;
};

function formatValue(
  value: string | number,
  locale: string,
  decimals: number | undefined,
): string {
  if (typeof value === "string") return value;
  return new Intl.NumberFormat(
    locale,
    decimals === undefined
      ? undefined
      : { minimumFractionDigits: decimals, maximumFractionDigits: decimals },
  ).format(value);
}

export function TextMorph({
  value: rawValue,
  options,
  locale = "en",
  decimals,
  disabled = false,
  respectReducedMotion = true,
  onAnimationStart,
  onAnimationComplete,
  onAnimationCancel,
  cursorIndex,
  className,
  render,
  ...props
}: TextMorphProps): React.ReactElement {
  const value = formatValue(rawValue, locale, decimals);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const stageRef = React.useRef<HTMLSpanElement>(null);
  const glyphsRef = React.useRef<HTMLSpanElement>(null);
  const ghostsRef = React.useRef<HTMLSpanElement>(null);
  const sheetRef = React.useRef<HTMLSpanElement>(null);
  // Set once: after that this component owns the glyph markup.
  const [initialHtml] = React.useState(() => ({ __html: glyphsHtml(value) }));
  const shown = React.useRef(value);
  const resolved = resolveOptions(options);
  const latest = React.useRef({
    options: resolved,
    disabled,
    respectReducedMotion,
    onAnimationStart,
    onAnimationComplete,
    onAnimationCancel,
    cursorIndex,
  });
  React.useLayoutEffect(() => {
    latest.current = {
      options: resolved,
      disabled,
      respectReducedMotion,
      onAnimationStart,
      onAnimationComplete,
      onAnimationCancel,
      cursorIndex,
    };
  });

  // The change in flight, so the next one can cancel it.
  const inFlight = React.useRef<(() => void) | null>(null);

  // Unmounted, a change in flight ends without calling back.
  const mounted = React.useRef(false);
  React.useLayoutEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      inFlight.current = null;
    };
  }, []);

  React.useLayoutEffect(() => {
    const root = rootRef.current;
    const stage = stageRef.current;
    const glyphs = glyphsRef.current;
    const ghosts = ghostsRef.current;
    const sheet = sheetRef.current;
    if (
      !root ||
      !stage ||
      !glyphs ||
      !ghosts ||
      !sheet ||
      value === shown.current
    )
      return;
    shown.current = value;
    inFlight.current?.();
    inFlight.current = null;

    const current = latest.current;
    const reduce =
      current.respectReducedMotion &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let over = false;
    const cancel = (): void => {
      if (over || !mounted.current) return;
      over = true;
      latest.current.onAnimationCancel?.();
    };
    inFlight.current = cancel;
    scheduleMorph({
      root,
      steps: morphTo(
        root,
        stage,
        glyphs,
        ghosts,
        sheet,
        value,
        current.options,
        { decimal: decimalFor(locale), caret: current.cursorIndex },
        // Read in the batch's first read phase, with the others.
        () =>
          current.disabled || !isOnScreen(root)
            ? "none"
            : reduce
              ? "reduced"
              : "full",
      ),
      done: (started) => {
        if (over || !mounted.current) return;
        if (started.length === 0) {
          delete glyphs.dataset.playing;
          over = true;
          if (inFlight.current === cancel) inFlight.current = null;
          latest.current.onAnimationComplete?.();
          return;
        }
        latest.current.onAnimationStart?.();
        void Promise.allSettled(started.map((a) => a.finished)).then(() => {
          if (over || !mounted.current) return;
          over = true;
          if (inFlight.current === cancel) inFlight.current = null;
          delete glyphs.dataset.playing;
          latest.current.onAnimationComplete?.();
        });
      },
    });
  }, [value, locale]);

  const defaultProps = {
    "data-slot": "text-morph",
    "data-mode": resolved.mode,
    className: cn("text-morph", className),
    children: (
      <>
        <span className="sr-only">{value}</span>
        <span
          ref={stageRef}
          aria-hidden="true"
          translate="no"
          className="text-morph-stage"
        >
          {/* Each glyph is its own box, which bidi treats as direction-
              neutral: without its own direction, a Latin value in a
              right-to-left paragraph would be laid out backwards. auto
              reads it off the value's first strong character. */}
          <span
            ref={glyphsRef}
            dir="auto"
            className="text-morph-glyphs"
            dangerouslySetInnerHTML={initialHtml}
          />
          <span ref={ghostsRef} className="text-morph-ghosts">
            <span ref={sheetRef} className="text-morph-ghost-sheet" />
          </span>
        </span>
      </>
    ),
  };

  return useRender({
    defaultTagName: "span",
    render,
    ref: rootRef,
    props: mergeProps<"span">(defaultProps, props),
  });
}

export { faster, MODE_DEFAULTS } from "./lib/options";
export type {
  TextMorphMode,
  TextMorphOptions,
  TextMorphOverrides,
  Timing,
} from "./lib/options";

import type { TextMorphMode } from "./options";

/*
 * Which glyphs of the old text survive into the new one. Pure: works on
 * grapheme strings, so it can be tested without a DOM.
 *
 * Numbers are matched by place value (torph): the digits line up on the
 * decimal point, so 1,204 → 1,318 keeps the thousands and the comma, and a
 * digit that changes rolls in place. Everything else is matched by the
 * mode's text rule: roll keeps the shared ends and one run between them
 * (Scritto); morph matches whole words first, then letters within the
 * words it pairs, and letters anywhere only in a one-word value (torph).
 *
 * A field someone is typing in knows where the edit happened, so with a
 * caret the whole value is matched around it instead (torph's cursorIndex):
 * typing 1 in front of 20 inserts a digit rather than renumbering the
 * column.
 */

/** `number`: part of a number matched by place value. */
export type GlyphKind = "text" | "number";

export type MatchResult = {
  /** For each new glyph, the index of the old glyph it keeps, or -1. */
  kept: number[];
  nextKinds: GlyphKind[];
  oldKinds: GlyphKind[];
  /** 1: the value went up (new glyphs arrive from below), -1: down. */
  trend: 1 | -1;
  /** Morph matched by words (the value has more than one). */
  byWords: boolean;
};

export type MatchOptions = {
  /** Match numbers by place value. */
  numbers: boolean;
  /** The locale's decimal separator. */
  decimal: string;
  /** 1 up, -1 down, 0 read it off the numbers. */
  trend: -1 | 0 | 1;
  /**
   * Where the caret sits in the new value after an edit. Matches around it
   * instead of by place value and the mode's text rule.
   */
  caret?: number;
  /**
   * Where the value is pinned as its length changes: 0 its start, 1 its end,
   * 0.5 its middle (centred). A roll run's travel is measured on screen,
   * against that, not along the text (Scritto's anchor).
   */
  anchor?: number;
};

type NumberToken = { start: number; end: number };

const graphemeSegmenter = new Intl.Segmenter(undefined, {
  granularity: "grapheme",
});
const wordSegmenter = new Intl.Segmenter(undefined, { granularity: "word" });

function graphemes(text: string): string[] {
  return Array.from(graphemeSegmenter.segment(text), (s) => s.segment);
}

/**
 * A letter or mark from a script whose letters join (Arabic and the scripts
 * written with it, Syriac, N'Ko, Mongolian, ...). Their digits don't join,
 * so they're left out.
 */
const JOINING =
  /(?=[\p{L}\p{M}])[\p{Script=Arabic}\p{Script=Syriac}\p{Script=Nko}\p{Script=Mongolian}\p{Script=Mandaic}\p{Script=Adlam}\p{Script=Hanifi_Rohingya}\p{Script=Thaana}]/u;

/**
 * The units a value animates in: one per grapheme, except that a word
 * written in a joining script stays whole. Its letters take their joined
 * forms only when drawn together, so splitting it would render each in its
 * isolated form. Everything else, digits included, is still per grapheme.
 */
export function textUnits(text: string): string[] {
  if (!JOINING.test(text)) return graphemes(text);
  const words = Array.from(wordSegmenter.segment(text), (s) => s.segment);
  return words.flatMap((word) =>
    JOINING.test(word) ? [word] : graphemes(word),
  );
}

/**
 * A caret given as a string index (an input's `selectionStart`, in UTF-16
 * code units) as a count of the units before it, which matching works in:
 * an emoji, an accented letter or a whole Arabic word before the caret is
 * several code units but one unit.
 */
export function caretUnits(units: string[], caret: number): number {
  let length = 0;
  let count = 0;
  for (const unit of units) {
    length += unit.length;
    if (length > caret) break;
    count++;
  }
  return count;
}

const SIGN = "+-−";
const GROUP = ".,'   \u066C\u066B";
/** Any script's decimal digits (0-9, ٠-٩, ۰-۹, ...). */
const DIGIT = /^\p{Nd}$/u;
/** Percent signs a number can end with, Latin and Arabic. */
const PERCENT = "%\u066A";
const CURRENCY = /^\p{Sc}$/u;

/** A decimal digit, in any script. */
export const isDigit = (g: string): boolean => DIGIT.test(g);

/** Marks a number may open with, besides a currency symbol. */
const PREFIX = SIGN + "(#" + PERCENT;
/** Marks a number may close with, besides a currency symbol. */
const SUFFIX = PERCENT + ".,!?:;)\"'\u201D\u2019";

const isBreak = (g: string): boolean => g === " " || g === "\t" || g === "\n";

/**
 * Numbers in a grapheme list. A number is a whole word (torph's rule):
 * digits with group or decimal separators between them, opened only by a
 * sign, currency symbol, `(` or `#` and closed only by punctuation, so
 * `v1.2.3`, `2024-01-01` and `COVID-19` stay text. The number itself takes
 * in a sign and currency symbol before it and a `%` after it.
 */
export function findNumbers(glyphs: string[]): NumberToken[] {
  const tokens: NumberToken[] = [];
  const isAffix = (g: string, marks: string): boolean =>
    marks.includes(g) || CURRENCY.test(g);
  let wordStart = 0;
  for (let i = 0; i <= glyphs.length; i++) {
    if (i < glyphs.length && !isBreak(glyphs[i])) continue;
    const wordFrom = wordStart;
    const wordEnd = i;
    let first = wordFrom;
    let last = wordEnd;
    wordStart = i + 1;
    while (first < last && isAffix(glyphs[first], PREFIX)) first++;
    while (last > first && isAffix(glyphs[last - 1], SUFFIX)) last--;
    if (first >= last || !isDigit(glyphs[first]) || !isDigit(glyphs[last - 1]))
      continue;
    const core = glyphs.slice(first, last);
    if (!core.every((g) => isDigit(g) || GROUP.includes(g))) continue;
    let start = first;
    // Leading currency symbol, then sign, either order.
    for (let k = 0; k < 2; k++) {
      const before = glyphs[start - 1];
      if (start > wordFrom && (CURRENCY.test(before) || SIGN.includes(before)))
        start--;
    }
    let end = last;
    if (end < wordEnd && PERCENT.includes(glyphs[end])) end++;
    tokens.push({ start, end });
  }
  return tokens;
}

/** Past this many digits gained or lost, a number is replaced, not moved. */
const MAGNITUDE_JUMP = 3;

/**
 * Pair two numbers' glyphs by place (torph's placeMatch), as [new, old]
 * index pairs. The shared prefix and suffix (a currency symbol, a `%`)
 * hold. Digits pair on the decimal point: by column while the count stays
 * the same, and as the longest run carried from the units column when it
 * changes, so `12,345` → `1,234` keeps 1234 sliding over. A separator holds
 * its distance from the point (sliding the comma one group along on
 * `999,999` → `1,000,000`) unless digits carried a reshape, when it would
 * have to cross them and leaves instead. Gaining or losing three digits or
 * more replaces the number: the two no longer read as one figure moving.
 */
export function matchPlaces(
  old: string[],
  next: string[],
  decimal: string,
): [number, number][] {
  const pairs = new Map<number, number>();
  let start = 0;
  while (
    start < old.length &&
    start < next.length &&
    old[start] === next[start] &&
    !isDigit(old[start])
  ) {
    pairs.set(start, start);
    start++;
  }
  let oldEnd = old.length;
  let nextEnd = next.length;
  while (
    oldEnd > start &&
    nextEnd > start &&
    old[oldEnd - 1] === next[nextEnd - 1] &&
    !isDigit(old[oldEnd - 1])
  ) {
    pairs.set(nextEnd - 1, oldEnd - 1);
    oldEnd--;
    nextEnd--;
  }

  // The decimal point, or the end where there is none.
  const pivotOf = (glyphs: string[], end: number): number => {
    for (let i = end - 1; i >= start; i--) if (glyphs[i] === decimal) return i;
    return end;
  };
  const digitsIn = (glyphs: string[], from: number, to: number): number[] => {
    const out: number[] = [];
    for (let i = from; i < to; i++) if (isDigit(glyphs[i])) out.push(i);
    return out;
  };
  const oldPivot = pivotOf(old, oldEnd);
  const nextPivot = pivotOf(next, nextEnd);
  const oldInt = digitsIn(old, start, oldPivot);
  const nextInt = digitsIn(next, start, nextPivot);
  // A side with no digits is a field being typed into or emptied.
  if (
    oldInt.length > 0 &&
    nextInt.length > 0 &&
    Math.abs(oldInt.length - nextInt.length) >= MAGNITUDE_JUMP
  ) {
    return [...pairs];
  }

  // Returns whether digits survived a change in their count.
  const pairDigits = (a: number[], b: number[], reshapes: boolean): boolean => {
    if (a.length === b.length || !reshapes) {
      for (let k = 0; k < Math.min(a.length, b.length); k++) {
        if (old[a[k]] === next[b[k]]) pairs.set(b[k], a[k]);
      }
      return false;
    }
    // From the units column, so ties on repeated digits resolve there.
    const carried = lcs(
      a.map((i) => old[i]).reverse(),
      b.map((i) => next[i]).reverse(),
    );
    for (const [to, from] of carried) {
      pairs.set(b[b.length - 1 - to], a[a.length - 1 - from]);
    }
    return carried.length > 0;
  };
  const separator = (from: number, to: number): void => {
    if (!isDigit(old[from]) && old[from] === next[to]) pairs.set(to, from);
  };

  if (!pairDigits(oldInt, nextInt, true)) {
    for (let k = 1; oldPivot - k >= start && nextPivot - k >= start; k++) {
      separator(oldPivot - k, nextPivot - k);
    }
  }
  // A fraction's columns are fixed by the point: 1.5 → 1.25 gains a
  // hundredths rather than sliding the 5.
  if (oldPivot < oldEnd && nextPivot < nextEnd) {
    pairs.set(nextPivot, oldPivot);
    for (let k = 1; oldPivot + k < oldEnd && nextPivot + k < nextEnd; k++) {
      separator(oldPivot + k, nextPivot + k);
    }
    pairDigits(
      digitsIn(old, oldPivot + 1, oldEnd),
      digitsIn(next, nextPivot + 1, nextEnd),
      false,
    );
  }
  return [...pairs];
}

/**
 * A decimal digit's value, in any script: digits run in blocks of ten from
 * zero, so it's the distance from the start of its run.
 */
export function digitValue(digit: string): number {
  const code = digit.codePointAt(0) ?? 0;
  let start = code;
  while (DIGIT.test(String.fromCodePoint(start - 1))) start--;
  return (code - start) % 10;
}

/** The numeric value of a number token, or NaN. */
export function parseNumber(glyphs: string[], decimal: string): number {
  let text = "";
  for (const g of glyphs) {
    if (isDigit(g)) text += digitValue(g);
    else if (g === decimal) text += ".";
    else if (g === "-" || g === "−") text = `-${text}`;
  }
  return Number(text);
}

/** Keep the shared start and end. Returns [newIndex, oldIndex] pairs. */
function matchEnds(
  old: string[],
  next: string[],
  anchor: number,
): [number, number][] {
  const pairs: [number, number][] = [];
  let start = 0;
  while (
    start < old.length &&
    start < next.length &&
    old[start] === next[start]
  ) {
    pairs.push([start, start]);
    start++;
  }
  let end = 0;
  while (
    end < old.length - start &&
    end < next.length - start &&
    old[old.length - 1 - end] === next[next.length - 1 - end]
  ) {
    pairs.push([next.length - 1 - end, old.length - 1 - end]);
    end++;
  }

  // Between them, one shared run flush with neither end (Scritto's
  // floating run): xxlightxx → yylightyy keeps "light". It must be at
  // least two glyphs (one shared letter is a coincidence) and may travel at
  // most its own length plus two slots, so a word never swims across the
  // value while everything around it dissolves.
  const run = floatingRun(
    old.slice(start, old.length - end),
    next.slice(start, next.length - end),
    anchor,
  );
  if (run) {
    for (let k = 0; k < run.length; k++) {
      pairs.push([start + run.to + k, start + run.from + k]);
    }
  }
  return pairs;
}

const MIN_RUN = 2;
const RUN_SLACK = 2;

/**
 * The longest shared run within its travel cap; the shorter trip on ties.
 * Travel is how far it moves on screen: in centred or end-pinned text the
 * value grows or shrinks about that point, so a run shifted along the text
 * by the change in length (or half of it) holds still.
 */
function floatingRun(
  old: string[],
  next: string[],
  anchor: number,
): { from: number; to: number; length: number } | null {
  const grown = next.length - old.length;
  const travelOf = (from: number, to: number): number =>
    Math.abs(to - from - anchor * grown);
  let best: { from: number; to: number; length: number } | null = null;
  // lengths[j]: the shared run ending at old[i - 1] and next[j - 1].
  let previous = new Array<number>(next.length + 1).fill(0);
  for (let i = 1; i <= old.length; i++) {
    const lengths = new Array<number>(next.length + 1).fill(0);
    for (let j = 1; j <= next.length; j++) {
      if (old[i - 1] !== next[j - 1]) continue;
      const length = previous[j - 1] + 1;
      lengths[j] = length;
      const from = i - length;
      const to = j - length;
      const travel = travelOf(from, to);
      if (length < MIN_RUN || travel > length + RUN_SLACK) continue;
      if (
        !best ||
        length > best.length ||
        (length === best.length && travel < travelOf(best.from, best.to))
      ) {
        best = { from, to, length };
      }
    }
    previous = lengths;
  }
  return best;
}

/** Match each glyph to the first unused old copy of it, in order. */
function matchAnywhere(old: string[], next: string[]): [number, number][] {
  const pool = new Map<string, number[]>();
  old.forEach((glyph, i) => pool.set(glyph, [...(pool.get(glyph) ?? []), i]));
  const pairs: [number, number][] = [];
  next.forEach((glyph, i) => {
    const from = pool.get(glyph)?.shift();
    if (from !== undefined) pairs.push([i, from]);
  });
  return pairs;
}

/** Longest common subsequence of two lists, as [bIndex, aIndex] pairs. */
function lcs(a: string[], b: string[]): [number, number][] {
  // lengths[i][j]: the LCS of a[i..] and b[j..].
  const lengths = Array.from({ length: a.length + 1 }, () =>
    new Array<number>(b.length + 1).fill(0),
  );
  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) {
      lengths[i][j] =
        a[i] === b[j]
          ? lengths[i + 1][j + 1] + 1
          : Math.max(lengths[i + 1][j], lengths[i][j + 1]);
    }
  }
  const pairs: [number, number][] = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) {
      pairs.push([j, i]);
      i++;
      j++;
    } else if (lengths[i + 1][j] >= lengths[i][j + 1]) {
      i++;
    } else {
      j++;
    }
  }
  return pairs;
}

/** Stands in for a whole number when comparing words: numbers pair by place. */
const NUMBER_KEY = "\u0000#";

type Word = {
  /** Its glyphs' indices in the value. */
  glyphs: number[];
  /** What it's compared by: its text, with each number as one token. */
  key: string[];
};

/** Words: runs of glyphs between spaces. */
function wordsOf(glyphs: string[], kinds: GlyphKind[]): Word[] {
  const words: Word[] = [];
  let word: Word | null = null;
  glyphs.forEach((glyph, i) => {
    if (glyph === " " || glyph === "\t" || glyph === "\n") {
      word = null;
      return;
    }
    if (!word) {
      word = { glyphs: [], key: [] };
      words.push(word);
    }
    // A number counts once, however many glyphs it has.
    if (kinds[i] === "text") word.key.push(glyph);
    else if (word.glyphs.length === 0 || kinds[i - 1] !== "number") {
      word.key.push(NUMBER_KEY);
    }
    word.glyphs.push(i);
  });
  return words;
}

/** Shared letters over the longer word's length; 1 for numbers alone. */
function similarity(a: string[], b: string[]): number {
  if (a.length === 0 || b.length === 0) return 0;
  return lcs(a, b).length / Math.max(a.length, b.length);
}

/** Below this a new word enters whole rather than morphing from an old one. */
const MIN_SIMILARITY = 0.4;

/** How many surviving words sit before each word: the gap it's in. */
function gaps(count: number, survivors: Set<number>): number[] {
  const out: number[] = [];
  let before = 0;
  for (let i = 0; i < count; i++) {
    out.push(before);
    if (survivors.has(i)) before++;
  }
  return out;
}

/**
 * Match by words (torph): words that survive in order keep every glyph, and
 * so do words that only moved (`hello world` → `world hello` swaps them
 * whole); a new word takes the letters it shares with the most similar old
 * word in the same gap between survivors, when they share enough; anything
 * else enters or leaves as a whole word. Only text glyphs pair here;
 * numbers were paired by place.
 */
function matchWords(
  old: string[],
  next: string[],
  oldKinds: GlyphKind[],
  nextKinds: GlyphKind[],
): [number, number][] {
  const oldWords = wordsOf(old, oldKinds);
  const nextWords = wordsOf(next, nextKinds);
  const keyOf = (word: Word): string => word.key.join("\u0001");
  const pairsOf = new Map<number, number>();

  const inOrder = lcs(oldWords.map(keyOf), nextWords.map(keyOf));
  for (const [to, from] of inOrder) pairsOf.set(to, from);
  const oldGaps = gaps(oldWords.length, new Set(inOrder.map(([, f]) => f)));
  const nextGaps = gaps(nextWords.length, new Set(inOrder.map(([t]) => t)));
  const taken = new Set(inOrder.map(([, from]) => from));

  // Words that moved: the same word, anywhere.
  nextWords.forEach((word, to) => {
    if (pairsOf.has(to)) return;
    const from = oldWords.findIndex(
      (old, i) => !taken.has(i) && keyOf(old) === keyOf(word),
    );
    if (from === -1) return;
    pairsOf.set(to, from);
    taken.add(from);
  });

  // Words that changed: the most similar old word in the same gap.
  nextWords.forEach((word, to) => {
    if (pairsOf.has(to)) return;
    let best = -1;
    let bestSimilarity = MIN_SIMILARITY;
    oldWords.forEach((old, from) => {
      if (taken.has(from) || oldGaps[from] !== nextGaps[to]) return;
      const shared = similarity(old.key, word.key);
      if (shared > bestSimilarity) {
        best = from;
        bestSimilarity = shared;
      }
    });
    if (best === -1) return;
    pairsOf.set(to, best);
    taken.add(best);
  });

  // Within each pair, the letters they share, in order.
  const pairs: [number, number][] = [];
  for (const [to, from] of pairsOf) {
    const a = oldWords[from].glyphs.filter((i) => oldKinds[i] === "text");
    const b = nextWords[to].glyphs.filter((i) => nextKinds[i] === "text");
    for (const [j, i] of lcs(
      a.map((k) => old[k]),
      b.map((k) => next[k]),
    )) {
      pairs.push([b[j], a[i]]);
    }
  }
  return pairs;
}

/**
 * Match around the caret of an edit. Group separators are set aside first,
 * since a field that formats as you type moves them around: the rest is
 * shared before the edit and shifted by its length after it, and the
 * separators pair up from the end.
 */
function matchCaret(
  old: string[],
  next: string[],
  caret: number,
  decimal: string,
): [number, number][] {
  const isSeparator = (g: string): boolean =>
    g !== decimal && GROUP.includes(g);
  const oldRest = old.flatMap((g, i) => (isSeparator(g) ? [] : [i]));
  const nextRest = next.flatMap((g, i) => (isSeparator(g) ? [] : [i]));
  const pairs: [number, number][] = [];
  const pair = (to: number, from: number): void => {
    if (old[oldRest[from]] === next[nextRest[to]]) {
      pairs.push([nextRest[to], oldRest[from]]);
    }
  };

  // The caret, counted in non-separator glyphs.
  const at = nextRest.filter((i) => i < caret).length;
  // Glyphs before the edit stay where they were; after it, they shift by
  // its length. Typing `grew` glyphs ends at the caret, deleting starts
  // there, and typing over a selection (grew 0) keeps everything in place.
  const grew = nextRest.length - oldRest.length;
  const before = grew > 0 ? at - grew : at;
  for (let k = 0; k < before; k++) pair(k, k);
  for (let k = at; k < nextRest.length; k++) pair(k, k - grew);

  const oldSeparators = old.flatMap((g, i) => (isSeparator(g) ? [i] : []));
  const nextSeparators = next.flatMap((g, i) => (isSeparator(g) ? [i] : []));
  for (
    let k = 1;
    k <= oldSeparators.length && k <= nextSeparators.length;
    k++
  ) {
    const from = oldSeparators[oldSeparators.length - k];
    const to = nextSeparators[nextSeparators.length - k];
    if (old[from] === next[to]) pairs.push([to, from]);
  }
  return pairs;
}

export function matchText(
  mode: TextMorphMode,
  old: string[],
  next: string[],
  options: MatchOptions,
): MatchResult {
  const kept = next.map(() => -1);
  const oldKinds: GlyphKind[] = old.map(() => "text");
  const nextKinds: GlyphKind[] = next.map(() => "text");
  const oldNumbers = options.numbers ? findNumbers(old) : [];
  const nextNumbers = options.numbers ? findNumbers(next) : [];
  const paired = Math.min(oldNumbers.length, nextNumbers.length);

  const caret = options.caret;
  const byWords =
    caret === undefined &&
    mode === "morph" &&
    (next.some(isBreak) || wordsOf(old, oldKinds).length > 1);

  // Numbers, paired in order, matched by place.
  let trend: 1 | -1 | 0 = options.trend;
  // Matching treats a number without a partner as text (a `$` left behind
  // by `$4` → `$` still matches), but its glyphs animate as a number's:
  // the 4 rolls out rather than fading like a letter, as torph's does.
  // A value that gains or loses a number, or changes none, reads as a rise.
  const result = (): MatchResult => {
    const asNumbers = (kinds: GlyphKind[], tokens: NumberToken[]) => {
      const shown = [...kinds];
      for (const { start, end } of tokens) shown.fill("number", start, end);
      return shown;
    };
    return {
      kept,
      nextKinds: asNumbers(nextKinds, nextNumbers),
      oldKinds: asNumbers(oldKinds, oldNumbers),
      trend: trend === -1 ? -1 : 1,
      byWords,
    };
  };
  for (let n = 0; n < paired; n++) {
    const a = oldNumbers[n];
    const b = nextNumbers[n];
    const aGlyphs = old.slice(a.start, a.end);
    const bGlyphs = next.slice(b.start, b.end);
    if (caret === undefined) {
      for (const [to, from] of matchPlaces(aGlyphs, bGlyphs, options.decimal)) {
        kept[b.start + to] = a.start + from;
      }
    }
    for (let i = a.start; i < a.end; i++) oldKinds[i] = "number";
    for (let i = b.start; i < b.end; i++) nextKinds[i] = "number";

    if (trend === 0) {
      const before = parseNumber(aGlyphs, options.decimal);
      const after = parseNumber(bGlyphs, options.decimal);
      if (after !== before) trend = after > before ? 1 : -1;
    }
  }

  // An edit at a caret: everything is matched around it.
  if (caret !== undefined) {
    for (const [to, from] of matchCaret(old, next, caret, options.decimal)) {
      kept[to] = from;
    }
    return result();
  }

  // Everything else, by the mode's text rule. Morph works by words once a
  // value has more than one.
  if (byWords) {
    for (const [to, from] of matchWords(old, next, oldKinds, nextKinds)) {
      kept[to] = from;
    }
    return result();
  }
  const oldText = old.flatMap((_, i) => (oldKinds[i] === "text" ? [i] : []));
  const nextText = next.flatMap((_, i) => (nextKinds[i] === "text" ? [i] : []));
  // A one-word value with digits in it that isn't a number (a clock, a
  // version) keeps its letters in order, as torph does: a digit reused from
  // another column would read as the time running backwards.
  const hasDigits = options.numbers && [...old, ...next].some(isDigit);
  const oldTexts = oldText.map((i) => old[i]);
  const nextTexts = nextText.map((i) => next[i]);
  const pairs =
    mode === "roll"
      ? matchEnds(oldTexts, nextTexts, options.anchor ?? 0)
      : hasDigits
        ? lcs(oldTexts, nextTexts)
        : matchAnywhere(oldTexts, nextTexts);
  for (const [to, from] of pairs) {
    kept[nextText[to]] = oldText[from];
  }

  return result();
}

/** The decimal separator for a locale. */
export function decimalFor(locale: string): string {
  return (
    new Intl.NumberFormat(locale)
      .formatToParts(1.1)
      .find((part) => part.type === "decimal")?.value ?? "."
  );
}

export type TextMorphMode = "roll" | "morph";

/** One CSS timing: a duration in ms and any CSS easing, `linear()` included. */
export type Timing = { duration: number; easing: string };

export type TextMorphOptions = {
  /**
   * `roll` keeps the old and new text's shared start and end, and rolls the
   * glyphs between vertically, on Scritto's defaults. `morph` matches whole
   * words, then letters within similar words (anywhere, in a one-word
   * value): shared ones slide to their new place, the rest scale and fade,
   * travelling with the nearest glyph that stays, on torph's defaults. Each mode brings its own defaults.
   */
  mode: TextMorphMode;
  /** Glyph movement: roll travel, enter/exit scale, shared glyphs sliding. */
  motion: Timing;
  /** Opacity and blur of arriving glyphs, optionally starting late. */
  fadeIn: Timing & { delay: number };
  /** Opacity and blur of leaving glyphs. */
  fadeOut: Timing;
  /** The box's width. */
  width: Timing;
  /**
   * `each`: every successive entering or leaving glyph starts `ms` later.
   * `spread`: a sweep from left to right across `ms` in total, by where
   * each glyph sits along the changed stretch.
   */
  stagger: { mode: "each" | "spread"; ms: number };
  /** Roll: travel (em), and the scale and tilt glyphs arrive and leave with. */
  roll: { distance: number; scale: number; rotate: number };
  /**
   * Morph: the scale letters grow from and shrink to. Digits of a number
   * roll instead, `distance` line heights, on their own fades.
   */
  morph: {
    scale: number;
    digits: { distance: number; fadeIn: Timing; fadeOut: Timing };
  };
  /** Blur on arriving and leaving glyphs, in em. */
  blur: number;
  /**
   * Match numbers by place value: digits line up on the decimal point, so
   * only the ones that changed roll.
   */
  numbers: boolean;
  /**
   * Which way glyphs roll (Scritto's trend). `auto` reads it off the value:
   * a number that grew brings new glyphs up from below, one that shrank
   * brings them down, and anything else rolls up. `up` and `down` hold one
   * way. Roll defaults to `auto`; morph to `down`, which is torph's: digits
   * fall in from above and leave downward, and a number's other marks
   * (separators, currency) arrive from below.
   */
  trend: "auto" | "up" | "down";
  /**
   * Fade old ink at an edge the box is shrinking away from. `auto` only
   * where it would land on something: a neighbour on the line, or the edge
   * of the pill or card holding the value.
   */
  edgeFade: "auto" | "always" | "never";
};

/** torph's digits: a full line of travel, fading out over 45% of the
 * duration and in over the first 25%. */
const TORPH_DIGITS: TextMorphOptions["morph"]["digits"] = {
  distance: 1,
  fadeIn: { duration: 100, easing: "linear" },
  fadeOut: { duration: 180, easing: "linear" },
};

/** The curve the box width eases on: fast out, no overshoot. */
const WIDTH_EASING = "cubic-bezier(0.22, 1, 0.36, 1)";
/** Ease-out expo: torph's movement, width and everything. */
const EXPO_EASING = "cubic-bezier(0.19, 1, 0.22, 1)";

/**
 * Scritto 0.1.0's defaults, from its source: a 550ms hand-tuned spring (1.5%
 * overshoot) on transform, opacity and blur alike; glyphs travel 0.35em while
 * scaling to 0.6 and tilting 2deg, blurred 0.1em; delays fan out over 30% of
 * the duration; the box eases on its own non-overshooting curve.
 */
const SCRITTO_SPRING =
  "linear(0,.1052,.3155,.532,.7112,.8414,.9265,.9765,1.0023,1.013,1.0151,1.0133,1.01,1.0068,1.0041,1.0022,1.001,1)";
const SCRITTO_OPTIONS: TextMorphOptions = {
  mode: "roll",
  motion: { duration: 550, easing: SCRITTO_SPRING },
  fadeIn: { duration: 550, easing: SCRITTO_SPRING, delay: 0 },
  fadeOut: { duration: 550, easing: SCRITTO_SPRING },
  width: { duration: 550, easing: WIDTH_EASING },
  stagger: { mode: "spread", ms: 165 },
  roll: { distance: 0.35, scale: 0.6, rotate: 2 },
  morph: { scale: 0.6, digits: TORPH_DIGITS },
  blur: 0.1,
  numbers: true,
  trend: "auto",
  edgeFade: "auto",
};

/**
 * torph 0.1.3's defaults, from its source: 400ms ease-out expo for movement
 * and width; arriving and leaving glyphs scale by 0.95; opacity is linear,
 * leaving over the first quarter of the duration and arriving over half of it
 * from a quarter in; no blur, no stagger.
 */
const TORPH_OPTIONS: TextMorphOptions = {
  mode: "morph",
  motion: { duration: 400, easing: EXPO_EASING },
  fadeIn: { duration: 200, easing: "linear", delay: 100 },
  fadeOut: { duration: 100, easing: "linear" },
  width: { duration: 400, easing: EXPO_EASING },
  stagger: { mode: "each", ms: 0 },
  roll: { distance: 0.35, scale: 0.95, rotate: 0 },
  morph: { scale: 0.95, digits: TORPH_DIGITS },
  blur: 0,
  numbers: true,
  trend: "down",
  edgeFade: "auto",
};

/** Each mode brings its own defaults: roll is Scritto's, morph is torph's. */
export const MODE_DEFAULTS: Record<TextMorphMode, TextMorphOptions> = {
  roll: SCRITTO_OPTIONS,
  morph: TORPH_OPTIONS,
};

/** Production: morph. */
export const DEFAULT_OPTIONS: TextMorphOptions = MODE_DEFAULTS.morph;

type Overrides<T> = {
  [K in keyof T]?: T[K] extends object ? Overrides<T[K]> : T[K];
};

/**
 * Any subset of the options, nested fields included: `{ motion: { duration:
 * 200 } }` keeps the mode's easing, `{ stagger: { ms: 50 } }` its stagger
 * mode.
 */
export type TextMorphOverrides = Overrides<TextMorphOptions>;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function merge<T>(base: T, overrides: Overrides<T> | undefined): T {
  if (!overrides) return base;
  const out: Record<string, unknown> = { ...(base as Record<string, unknown>) };
  for (const [key, value] of Object.entries(overrides)) {
    if (value === undefined) continue;
    out[key] =
      isRecord(value) && isRecord(out[key])
        ? merge(out[key], value as Overrides<unknown>)
        : value;
  }
  return out as T;
}

/** Options for `overrides`, filled in from the chosen mode's defaults. */
export function resolveOptions(
  overrides: TextMorphOverrides = {},
): TextMorphOptions {
  return merge(
    MODE_DEFAULTS[overrides.mode ?? DEFAULT_OPTIONS.mode],
    overrides,
  );
}

/**
 * The same look on a shorter clock: every duration, delay and stagger scaled
 * by `factor`. For labels that answer a click (the docs use 209ms of motion)
 * or mirror typing, where the mode's full timing would lag behind the input.
 */
export function faster(o: TextMorphOptions, factor: number): TextMorphOptions {
  const t = (timing: Timing): Timing => ({
    ...timing,
    duration: Math.round(timing.duration * factor),
  });
  return {
    ...o,
    motion: t(o.motion),
    fadeIn: { ...t(o.fadeIn), delay: Math.round(o.fadeIn.delay * factor) },
    fadeOut: t(o.fadeOut),
    width: t(o.width),
    stagger: { ...o.stagger, ms: Math.round(o.stagger.ms * factor) },
    morph: {
      ...o.morph,
      digits: {
        ...o.morph.digits,
        fadeIn: t(o.morph.digits.fadeIn),
        fadeOut: t(o.morph.digits.fadeOut),
      },
    },
  };
}

/* TextMorph (registry/default/text-morph). The server renders one span per
   glyph, the same markup the browser keeps, so these styles apply from first
   paint and nothing shifts on hydration. */

/* A glyph's slot: how far it reaches above and below the glyph's box, and
   how far it fades across. Roll (Scritto) fades across 0.3em of room past
   the box, for its blur and tilt; morph (torph) fades 0.15em inside the
   box itself, so a digit rolling in shows nothing until it enters its line
   (with room past it, it showed faintly, whole, above the line). */
.text-morph {
  --text-morph-slot-y: 0.3em;
  --text-morph-fade: 0.3em;
  position: relative;
}
.text-morph[data-mode="morph"] {
  --text-morph-slot-y: 0em;
  --text-morph-fade: 0.15em;
}
.text-morph {
  --text-morph-fade-y: linear-gradient(
    to bottom,
    transparent,
    #000 var(--text-morph-fade),
    #000 calc(100% - var(--text-morph-fade)),
    transparent
  );
}

/* It flows like the text around it, wrapping between words where the
   context lets text wrap, and never changes display: switching between
   inline and inline-block repaints the text snapped differently. In a
   layer, so a class can make it a box instead (`block`, `inline-block`),
   which eases its height when its line count changes; the rest stays
   unlayered, so page styles for spans can't reach the glyphs. */
@layer components {
  .text-morph {
    display: inline;
    vertical-align: baseline;
  }
}

/* While a one-line change eases the label's space, it stays on one line.
   text-wrap-mode leaves spaces alone; nowrap (the fallback) would drop a
   leading one. A box's text sits at its start meanwhile: the stage rides it
   to where its alignment puts it, from the width as layout rounds it (both
   rounded on their own, the text stepped back and forth). */
.text-morph[data-sizing] {
  white-space: nowrap;
  text-align: start;
}
@supports (text-wrap-mode: nowrap) {
  .text-morph[data-sizing] {
    white-space: inherit;
    text-wrap-mode: nowrap;
  }
}

/* The plain value for screen readers, exactly as written (sr-only's
   nowrap would drop a leading space). The visible glyphs are what gets
   selected and copied, so this copy isn't, or a copied selection would
   paste the value twice (torph does the same). */
.text-morph > .sr-only {
  white-space: pre;
  user-select: none;
}

.text-morph-stage {
  position: relative;
}

/* Each glyph sits in a slot with room above and below its line and room
   beside it for tilt, scale and blur, plus the length of any slide along
   the line (--reach). Negative margins hand the room back, so the slot
   takes no space. While a change plays (data-playing) the slot fades its
   glyph out above and below; at rest it doesn't, so no masks stay on the
   page. Toggling an attribute costs a scoped restyle, where adding or
   removing the slots restyles the page. A mask cuts whatever falls outside
   its element, so a glyph moving to another line turns it off. */
.text-morph-slot {
  display: inline-block;
  padding: var(--text-morph-slot-y) calc(0.5em + var(--reach, 0px));
  margin: calc(-1 * var(--text-morph-slot-y)) calc(-0.5em - var(--reach, 0px));
}
.text-morph-glyphs[data-playing] .text-morph-slot:not([data-travel]) {
  mask-image: var(--text-morph-fade-y);
}

/* Where the browser can, the fade reaches sideways without end (torph's
   slots do the same): it only ever cuts above and below, so a glyph sliding
   or shrinking sideways out of its slot is never sliced. Elsewhere the slot's
   room (--reach) and unmasking a shape's glyphs cover it. no-clip lifts
   the cut above and below as well, showing a glyph rolling in whole and
   unfaded past its slot, so a clip puts that edge back, reaching sideways
   without end. */
@supports (mask-clip: no-clip) {
  .text-morph-glyphs[data-playing] .text-morph-slot:not([data-travel]),
  .text-morph-ghost:not([data-travel]) {
    mask-repeat: repeat-x;
    mask-clip: no-clip;
    clip-path: inset(0 -100vw);
  }
}

/* An empty value still holds its line (torph does the same): with nothing
   in it, the line would collapse and the text around it jump. */
.text-morph-glyphs:empty::before {
  content: "\200B";
}

/* Spaces show as typed (torph does the same): a run of them isn't
   collapsed to one, and a line break in the value breaks the line. Only
   collapsing changes; wrapping is inherited, so a label easing its width
   still holds one line. */
.text-morph [data-space] {
  white-space: pre-wrap;
}
@supports (white-space-collapse: preserve) {
  .text-morph [data-space] {
    white-space: inherit;
    white-space-collapse: preserve;
  }
}

/* A word never breaks; lines break at the spaces between words. */
.text-morph [data-word] {
  white-space: nowrap;
}

/* Glyphs keep their own compositing layer, animating or not. A glyph that
   drops back into ordinary painting when its animation ends is redrawn
   snapped to the pixel grid, often with different anti-aliasing: a visible
   twitch just as it settles (torph does the same). */
.text-morph [data-glyph]:not([data-space]) {
  display: inline-block;
  will-change: transform, opacity;
}

/* Ghosts sit at --x/--y from the anchor's place in the flow (its static
   position, where the value is on its line). The anchor never changes size;
   the sheet inside it is offset and sized each change to take in every
   ghost, and wears the edge fade (--text-morph-edge) only while a shrinking
   box would leave ink over a neighbour. */
.text-morph-ghosts {
  position: absolute;
  /* Inline, so its static position is where the value sits on its line. */
  display: inline;
  width: 0;
  height: 0;
  pointer-events: none;
  /* Glyphs on their way out aren't part of the value. */
  user-select: none;
}
.text-morph-ghost-sheet {
  position: absolute;
  left: var(--ox, 0px);
  top: var(--oy, 0px);
  width: 0;
  height: 0;
  direction: ltr;
  mask-image: var(--text-morph-edge, none);
  mask-repeat: no-repeat;
}

/* Each ghost gets a slot at its own line, faded above and below like the
   live glyphs, with room beside it for tilt, scale and blur. A ghost
   travelling with a neighbour moves its slot, fade and all (translate),
   and leaves inside it. */
.text-morph-ghost {
  position: absolute;
  left: calc(var(--x) - var(--ox, 0px) - 0.5em);
  top: calc(var(--y) - var(--oy, 0px) - var(--text-morph-slot-y));
  padding: var(--text-morph-slot-y) 0.5em;
  white-space: nowrap;
  mask-image: var(--text-morph-fade-y);
}
/* A ghost swapped as part of a shape slides toward the shape's centre as
   it shrinks, out of its slot; it doesn't roll, so it goes unmasked. */
.text-morph-ghost[data-travel] {
  mask-image: none;
}
